// Q1: Return the sum of the first n elements of arr.
int sumArray(const int arr[], int n);

// Q2: Return the largest value among the first n elements of arr.
// (n is guaranteed to be >= 1.)
int findMax(const int arr[], int n);

// Q3: Reverse the first n elements of arr in place.
void reverseArray(int arr[], int n);

// Q4: Return true if the first n elements of arr are sorted in
// non-decreasing order (ascending, duplicates allowed), false otherwise.
// An array with 0 or 1 elements is always sorted.
bool isSorted(const int arr[], int n);

// Q5: Return how many of the first n elements are strictly greater
// than the average of all n elements. Use integer arithmetic rules of
// C++ for the comparison (compare arr[i] * n > sum, do NOT use floats).
int countGreaterThanAverage(const int arr[], int n);
